double totalMass = 0.0;
for (size_t i = 0; i < masses.size(); ++i) {
    totalMass += masses[i];
}
std::random_device rd;
std::mt19937 gen(rd());
for (size_t i = 0; i < velocities.size(); ++i) {
    double sigma = std::sqrt(temperature / masses[i]);
    std::normal_distribution<double> dist(0.0, sigma);
    velocities[i].x = dist(gen);
    velocities[i].y = dist(gen);
    velocities[i].z = dist(gen);
}
vec3 momentum(0.0, 0.0, 0.0);
for (size_t i = 0; i < velocities.size(); ++i) {
    momentum.x += masses[i] * velocities[i].x;
    momentum.y += masses[i] * velocities[i].y;
    momentum.z += masses[i] * velocities[i].z;
}
vec3 comVelocity = momentum / totalMass;
for (size_t i = 0; i < velocities.size(); ++i) {
    velocities[i].x -= comVelocity.x;
    velocities[i].y -= comVelocity.y;
    velocities[i].z -= comVelocity.z;
}

